import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"CERN Open Data: four routes, one gap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"CERN Open Data: four routes, one gap | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/docs/CERN-ENUMERATION.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"CERN Open Data: four routes, one gap | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/docs/CERN-ENUMERATION.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/docs/CERN-ENUMERATION.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/docs/CERN-ENUMERATION.html"}]]},"headers":[],"relativePath":"docs/CERN-ENUMERATION.md","filePath":"docs/CERN-ENUMERATION.md"}`),a={name:`docs/CERN-ENUMERATION.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="cern-open-data-four-routes-one-gap" tabindex="-1">CERN Open Data: four routes, one gap <a class="header-anchor" href="#cern-open-data-four-routes-one-gap" aria-label="Permalink to “CERN Open Data: four routes, one gap”">​</a></h1><p>Measured 2026-09-05 against <code>opendata.cern.ch</code>. Reproduce with <code>npm run cern</code> and <code>npm run cern:oai</code>.</p><p><em>Figures below are written by <code>npm run cern</code> from its last run, never by hand (<code>docs/cern-measured.json</code> is the record; this block is its rendering).</em></p><table tabindex="0"><thead><tr><th>measured</th><th>count</th></tr></thead><tbody><tr><td>canonical records (slug aliases resolved)</td><td>62,889</td></tr><tr><td>sitemap URL ids</td><td>111,605</td></tr><tr><td>slug aliases among them</td><td>59,175</td></tr><tr><td>child sitemaps</td><td>318</td></tr><tr><td>record URLs listed</td><td>151,383</td></tr></tbody></table><h2 id="the-headline" tabindex="-1">The headline <a class="header-anchor" href="#the-headline" aria-label="Permalink to “The headline”">​</a></h2><p><strong>No route enumerates the portal completely, and two of them fail silently.</strong> The four sources do not even agree on what a record <em>is</em>.</p><table tabindex="0"><thead><tr><th>route</th><th style="text-align:right;">count</th><th>what it misses</th></tr></thead><tbody><tr><td>REST aggregate count</td><td style="text-align:right;">82,385</td><td>nothing known, but refuses paging past offset 10,000</td></tr><tr><td>OAI-PMH <code>ListIdentifiers</code></td><td style="text-align:right;">74,614</td><td>9.4% short of REST — <strong>and reports no error</strong></td></tr><tr><td>sitemap, canonical records</td><td style="text-align:right;">61,497</td><td>Documentation, Glossary, and 13,126 OAI records</td></tr><tr><td>any <code>recid</code>-keyed query</td><td style="text-align:right;">72,111</td><td>10,274 records carry no indexed <code>recid</code> at all</td></tr></tbody></table><p><code>robots.txt</code> carries <code>Disallow: /api/</code> and advertises the sitemap, so the sitemap and OAI are the sanctioned bulk routes. Their union is 74,619 canonical records.</p><h2 id="where-the-gap-actually-is" tabindex="-1">Where the gap actually is <a class="header-anchor" href="#where-the-gap-actually-is" aria-label="Permalink to “Where the gap actually is”">​</a></h2><p>It is <strong>concentrated by record type</strong>, not spread across the corpus:</p><table tabindex="0"><thead><tr><th>type</th><th style="text-align:right;">total</th><th>outside the OAI ∪ sitemap union</th></tr></thead><tbody><tr><td>Dataset</td><td style="text-align:right;">66,042</td><td>0 / 15 sampled</td></tr><tr><td>Supplementaries</td><td style="text-align:right;">5,904</td><td>0 / 40</td></tr><tr><td>Environment</td><td style="text-align:right;">64</td><td>0 / 40</td></tr><tr><td>Software</td><td style="text-align:right;">55</td><td>0 / 40</td></tr><tr><td><strong>Documentation</strong></td><td style="text-align:right;"><strong>9,272</strong></td><td><strong>40 / 40</strong></td></tr><tr><td><strong>Glossary</strong></td><td style="text-align:right;"><strong>1,006</strong></td><td><strong>40 / 40</strong></td></tr></tbody></table><p><strong>10,278 records — 12.5% of the corpus — are reachable only through the REST API.</strong> Their ids are pure slugs (<code>AOD</code>, <code>Barn</code>, <code>stripping21r1-dy2mumuline3</code>) with no trailing recid, which is the same population as the &quot;10,274 records carry no indexed <code>recid</code>&quot; figure seen from the other side.</p><h2 id="slug-ids-are-aliases-except-when-they-are-not" tabindex="-1">Slug ids are aliases, except when they are not <a class="header-anchor" href="#slug-ids-are-aliases-except-when-they-are-not" aria-label="Permalink to “Slug ids are aliases, except when they are not”">​</a></h2><p><code>/record/cms-68283</code> and <code>/record/68283</code> serve the same record — verified by fetching both. 51,732 of the 55,821 slug URLs in the sitemap are aliases of this form, so counting them as records inflates the corpus from 61,497 to 113,229.</p><p>The alias rule that survives testing: <strong><code>&lt;prefix&gt;-&lt;N&gt;</code> is an alias iff <code>N</code> is a recid known from ANY source.</strong> Two narrower rules both failed —</p><ul><li><em>any trailing digits</em> → turned <code>stripping21r1-dy2mumuline3</code> into record <code>&quot;3&quot;</code></li><li><em>trailing digits in the sitemap&#39;s own numeric set</em> → left 4,085 slugs (<code>alice-1100</code>, <code>atlas-15003</code>) looking like new records, when they alias records only the OAI feed lists numerically</li></ul><p>Five records resist every rule: <code>cms-93957</code>–<code>cms-93961</code>. <code>/record/cms-93957</code> returns 200 with the title &quot;Sign in to CERN&quot;, <code>/record/93957</code> is 404, and REST returns 0 hits for both forms. <strong>Listed in the public sitemap, not publicly retrievable, absent from every public API.</strong> Reported, not probed.</p><h2 id="not-established" tabindex="-1">Not established <a class="header-anchor" href="#not-established" aria-label="Permalink to “Not established”">​</a></h2><p>The portal reports 82,385 records while <code>type:*</code> matches 82,375. <strong>Those ten cannot be isolated.</strong> Every negation the query interface accepts returns HTTP 502, and the one form that answers cannot be trusted:</p><table tabindex="0"><thead><tr><th>query</th><th>result</th></tr></thead><tbody><tr><td><code>NOT type:*</code>, <code>-type:*</code>, <code>NOT _exists_:type</code></td><td>502</td></tr><tr><td><code>NOT type.primary:*</code>, <code>-type.primary:*</code>, <code>type.primary:(NOT *)</code></td><td>502</td></tr><tr><td><code>NOT _exists_:type.primary</code>, <code>*:* -type.primary:*</code></td><td>502</td></tr><tr><td><code>_missing_:type</code></td><td><strong>0</strong> — indistinguishable from unsupported</td></tr></tbody></table><p>That last row is the important one: a <code>0</code> from a syntax the server may simply not implement is not a measurement, it is a vacuous zero of exactly the kind this document exists to warn about. Set difference would find them, but only from a full REST enumeration, which the 10,000-offset cap and <code>robots.txt</code> both preclude. <strong>They exist, they are uncharacterised, and the search is exhausted at this access level</strong> — recorded so it is not repeated.</p><h2 id="what-this-cost-and-the-rules-that-came-out-of-it" tabindex="-1">What this cost, and the rules that came out of it <a class="header-anchor" href="#what-this-cost-and-the-rules-that-came-out-of-it" aria-label="Permalink to “What this cost, and the rules that came out of it”">​</a></h2><p>The corpus size was answered wrongly twice and the membership wrongly twice more, across five passes.</p><ol><li><strong>Corroboration is not correctness.</strong> The broken numeric-only filter returned 82,385 record URLs — exactly REST&#39;s independently reported total. That agreement is what stopped the checking. A lone convenient number still invites scrutiny; a <em>matching</em> one closes the question.</li><li><strong>A correction gets less scrutiny than what it replaces.</strong> Having found the filter defect, the replacement (113,229) shipped 84% too high with no check on what the newly admitted ids were.</li><li><strong>A right count with wrong members passes every check that counts and fails every check that compares.</strong> 61,497 was correct from the third pass on and never moved, while the membership was wrong twice underneath it. Only comparison against a second corpus exposed it.</li><li><strong>Sample a partition, not a slice.</strong> A prediction that 9.4% of REST records would fall outside the union measured 0 of 250 — because deep paging is capped, so the sample covered 8.5% of the corpus from one end. Sampling by <em>type</em> found the gap in one request.</li></ol>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};